// Verifies the Signalroom HMAC before anything else runs.
// Requires the raw body: the Webhook node has "Raw Body" enabled, so the
// exact bytes Signalroom signed are in $binary.data (base64).
const crypto = require('crypto');
const secret = $env.SIGNALROOM_WEBHOOK_SECRET;
if (!secret) throw new Error('SIGNALROOM_WEBHOOK_SECRET is not set');

const item = $input.first();
const raw = Buffer.from(item.binary.data.data, 'base64');
const headers = item.json.headers || {};
const given = String(headers['x-signalroom-signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');

const a = Buffer.from(given);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid Signalroom signature');
}

const payload = JSON.parse(raw.toString('utf8'));
// Replay guard: sent_at is inside the signed body.
const ageMs = Date.now() - Date.parse(payload.sent_at);
if (!(ageMs >= -60000 && ageMs <= 5 * 60000)) {
  throw new Error('Stale Signalroom delivery');
}
return [{ json: payload }];

